/* Study OS — instructor practice exam for Principles of Economics (macro): 250 multiple-choice questions,
   50 per topic (GDP -> g, business cycle & unemployment -> b, inflation -> i, AD-AS -> a, fiscal policy -> f).
   Added 24 Nov 2026 from the owner's file "Macroeconomics Practice Exam (250 Questions)". Wording kept; maths
   written as plain text; the five questions that said "Question N" now repeat their data.
   Explanations: worked solutions for calculation questions, the correct answer otherwise.
   opts[0] is the correct answer. ids ex-<chapter><n> are stable: never renumber (answers are saved by id).
   Appended to window.ECO_PRACTICE_MCQ so the course engine shows them with the other practice questions. */
window.ECO_PRACTICE_MCQ=(window.ECO_PRACTICE_MCQ||[]).concat([
{id:"ex-g1",cat:"g",q:"Gross Domestic Product (GDP) is officially defined as the market value of all:",opts:["final goods and services produced within a nation's borders in a given period of time.","goods and services sold within a nation in a given year.","final goods and services produced by a nation's citizens anywhere in the world.","intermediate and final goods produced domestically during a year."],exp:"Correct answer: final goods and services produced within a nation's borders in a given period of time."},
{id:"ex-g2",cat:"g",q:"Which of the following transactions is excluded from GDP to avoid double counting?",opts:["A bakery purchasing flour to make bread for sale.","A consumer buying a new smartphone.","The government building a new highway.","A family purchasing a newly constructed house."],exp:"Correct answer: A bakery purchasing flour to make bread for sale."},
{id:"ex-g3",cat:"g",q:"In the expenditure approach to calculating GDP, the correct formula is:",opts:["GDP = C + I + G + (X - M)","GDP = C + I + G + (X + M)","GDP = C + I + G - (X - M)","GDP = C + S + T + (X - M)"],exp:"Correct answer: GDP = C + I + G + (X - M)"},
{id:"ex-g4",cat:"g",q:"Which of the following is NOT included in U.S. or Thai GDP?",opts:["The purchase of a secondhand Toyota Camry from a private owner.","The salary of a public school teacher.","The sale of domestically grown rice to a foreign country.","A business purchasing new computer servers."],exp:"Correct answer: The purchase of a secondhand Toyota Camry from a private owner."},
{id:"ex-g5",cat:"g",q:"Government transfer payments, such as Social Security benefits or unemployment compensation, are:",opts:["excluded from GDP because they do not represent payment for current production.","included in the G component of GDP.","included in the C component of GDP.","included in Net Exports."],exp:"Correct answer: excluded from GDP because they do not represent payment for current production."},
{id:"ex-g6",cat:"g",q:"Suppose a farmer grows wheat and sells it to a miller for $100. The miller turns it into flour and sells it to a baker for $250. The baker makes bread and sells it to consumers for $400. How much does this entire process contribute to GDP?",opts:["$400","$750","$350","$100"],exp:"Count only the final good: bread, $400. Wheat and flour are intermediate goods (counting them would be double counting)."},
{id:"ex-g7",cat:"g",q:"Which of the following would be classified under Gross Private Domestic Investment (I) in the GDP accounts?",opts:["A household buying a newly built condominium.","A household buying 100 shares of Apple stock.","The government purchasing new fighter jets.","A consumer buying a new refrigerator for home use."],exp:"Correct answer: A household buying a newly built condominium."},
{id:"ex-g8",cat:"g",q:"Nonmarket transactions, such as unpaid housework and childcare performed by a parent at home, are:",opts:["excluded from GDP, which causes GDP to understate total economic production.","estimated and added to GDP.","included under the services category of Personal Consumption (C).","counted only if the parent has a college degree."],exp:"Correct answer: excluded from GDP, which causes GDP to understate total economic production."},
{id:"ex-g9",cat:"g",q:"If Nominal GDP is $5,500 billion and the GDP chain price index (GDP deflator) is 110, what is Real GDP?",opts:["$5,000 billion","$6,050 billion","$5,390 billion","$500 billion"],exp:"Real GDP = 5,500 ÷ 110 × 100 = 5,000 billion."},
{id:"ex-g10",cat:"g",q:"When the domestic currency appreciates (becomes stronger) against foreign currencies, what typically happens to Net Exports (X - M) and GDP, holding everything else constant?",opts:["Exports fall, imports rise, and GDP decreases.","Exports rise, imports fall, and GDP increases.","Both exports and imports rise, leaving GDP unchanged.","Net exports increase because foreign goods become more expensive."],exp:"Correct answer: Exports fall, imports rise, and GDP decreases."},
{id:"ex-g11",cat:"g",q:"Which category accounts for the largest share of GDP under the expenditure approach in most developed economies?",opts:["Personal Consumption Expenditures (C)","Gross Private Domestic Investment (I)","Government Consumption and Investment (G)","Net Exports (X - M)"],exp:"Correct answer: Personal Consumption Expenditures (C)"},
{id:"ex-g12",cat:"g",q:"Goods that last for more than three years, such as automobiles and washing machines, are classified under Personal Consumption (C) as:",opts:["durable goods.","nondurable goods.","capital goods.","intermediate goods."],exp:"Correct answer: durable goods."},
{id:"ex-g13",cat:"g",q:"If a country's Exports (X) equal $400 billion and Imports (M) equal $480 billion, then Net Exports equal:",opts:["-$80 billion.","$880 billion.","$80 billion.","-$480 billion."],exp:"Net exports = X − M = 400 − 480 = −80 billion."},
{id:"ex-g14",cat:"g",q:"Which of the following is a major shortcoming of using GDP as a measure of societal well-being?",opts:["It ignores income distribution, leisure time, and environmental degradation (economic bads).","It counts intermediate goods multiple times.","It overstates production by including black-market transactions.","It adjusts too heavily for improvements in product quality."],exp:"Correct answer: It ignores income distribution, leisure time, and environmental degradation (economic bads)."},
{id:"ex-g15",cat:"g",q:"Suppose an economy produces only two goods: Apples and Oranges. In Year 1 (Base Year), 100 Apples are produced at $1 each and 50 Oranges at $2 each. In Year 2, 120 Apples are produced at $1.50 each and 60 Oranges at $2.50 each. What is Real GDP in Year 2?",opts:["$240","$330","$200","$300"],exp:"Real GDP uses base-year prices: 120 × $1 + 60 × $2 = $240."},
{id:"ex-g16",cat:"g",q:"Suppose an economy produces only two goods: Apples and Oranges. In Year 1 (Base Year), 100 Apples are produced at $1 each and 50 Oranges at $2 each. In Year 2, 120 Apples are produced at $1.50 each and 60 Oranges at $2.50 each. What is the GDP Deflator (chain price index) in Year 2?",opts:["137.5","100.0","165.0","72.7"],exp:"Nominal GDP in Year 2 = 120 × 1.50 + 60 × 2.50 = 330. Deflator = 330 ÷ 240 × 100 = 137.5."},
{id:"ex-g17",cat:"g",q:"In the Circular Flow Model, households supply factors of production to businesses in the:",opts:["resource (factor) market.","product market.","financial market.","foreign exchange market."],exp:"Correct answer: resource (factor) market."},
{id:"ex-g18",cat:"g",q:"Which of the following is included in the Income Approach to measuring GDP?",opts:["Compensation of employees, rents, net interest, and corporate profits","Personal consumption expenditures","Net exports and government purchases","Transfer payments and capital gains from stock sales"],exp:"Correct answer: Compensation of employees, rents, net interest, and corporate profits"},
{id:"ex-g19",cat:"g",q:"A Japanese-owned Toyota factory operating in Thailand produces cars worth 10 billion Baht. How is this production recorded?",opts:["In Thailand's GDP.","In Japan's GDP and Thailand's GNP.","Neither in Thailand's GDP nor Japan's GDP.","Only in Japan's GDP because Toyota is a Japanese company."],exp:"GDP counts production inside the country's borders, whoever owns the factory."},
{id:"ex-g20",cat:"g",q:"Unsold goods produced by a firm during the current year are:",opts:["included in current-year GDP as part of business inventory investment (I).","excluded from current-year GDP until they are sold.","subtracted from Personal Consumption (C).","counted as intermediate goods."],exp:"Correct answer: included in current-year GDP as part of business inventory investment (I)."},
{id:"ex-g21",cat:"g",q:"Real GDP differs from Nominal GDP because Real GDP:",opts:["is adjusted for changes in the price level (inflation).","excludes government spending.","includes the underground economy.","is measured using current-year prices."],exp:"Correct answer: is adjusted for changes in the price level (inflation)."},
{id:"ex-g22",cat:"g",q:"If Nominal GDP rises by 6% in a given year while the price level rises by 4%, Real GDP has approximately:",opts:["risen by 2%.","fallen by 2%.","risen by 10%.","remained unchanged."],exp:"Real growth ≈ nominal growth − inflation = 6% − 4% = 2%."},
{id:"ex-g23",cat:"g",q:"Buying and selling existing stocks and bonds on the Stock Exchange of Thailand (SET) is excluded from GDP because:",opts:["these are purely financial transactions that merely transfer ownership of existing assets.","stockbrokers do not pay taxes.","stocks are intermediate goods.","only foreign stocks count toward GDP."],exp:"Correct answer: these are purely financial transactions that merely transfer ownership of existing assets."},
{id:"ex-g24",cat:"g",q:"Which of the following represents a \"nondurable good\" in GDP accounting?",opts:["Groceries and gasoline","A new dining table","A haircut","A commercial delivery truck"],exp:"Correct answer: Groceries and gasoline"},
{id:"ex-g25",cat:"g",q:"If GDP is $1,200 billion, Consumption (C) is $800 billion, Government Spending (G) is $250 billion, Exports (X) are $100 billion, and Imports (M) are $150 billion, what is Gross Private Domestic Investment (I)?",opts:["$200 billion","$100 billion","$150 billion","$250 billion"],exp:"I = GDP − C − G − (X − M) = 1,200 − 800 − 250 − (−50) = 200."},
{id:"ex-g26",cat:"g",q:"The underground economy (informal sector) refers to:",opts:["unreported legal and illegal economic activities that are omitted from official GDP statistics.","subway construction projects.","mining and agricultural industries.","international trade conducted via sea freight."],exp:"Correct answer: unreported legal and illegal economic activities that are omitted from official GDP statistics."},
{id:"ex-g27",cat:"g",q:"Suppose a homeowner pays a landscaping company $200 a month to mow their lawn. Later, the homeowner marries the landscaper, and the landscaper continues to mow the lawn for free. As a result, official GDP:",opts:["decreases by $200 per month.","increases by $200 per month.","remains unchanged.","doubles."],exp:"The $200 service was counted in GDP; unpaid work is not, so GDP falls by $200 a month."},
{id:"ex-g28",cat:"g",q:"What happens to GDP when a government cleans up a massive toxic oil spill?",opts:["GDP increases because spending on cleanup services is counted as production, despite the loss in environmental quality.","GDP decreases because of environmental damage.","GDP remains completely unaffected.","Net exports automatically increase."],exp:"Correct answer: GDP increases because spending on cleanup services is counted as production, despite the loss in environmental quality."},
{id:"ex-g29",cat:"g",q:"GDP per capita is calculated by dividing a nation's GDP by its:",opts:["total population.","civilian labor force.","inflation rate.","total land area."],exp:"Correct answer: total population."},
{id:"ex-g30",cat:"g",q:"Which of the following is a problem when comparing GDP per capita between Industrially Advanced Countries (IACs) and Less-Developed Countries (LDCs)?",opts:["Measurement errors are typically greater in LDCs, and exchange rate conversions can distort true purchasing power.","LDCs have fewer nonmarket transactions than IACs.","IACs do not report their service sector output.","GDP per capita fully accounts for income inequality."],exp:"Correct answer: Measurement errors are typically greater in LDCs, and exchange rate conversions can distort true purchasing power."},
{id:"ex-g31",cat:"g",q:"In a simple circular flow model with no government or foreign sector, total income earned by households must equal:",opts:["the dollar value of total output produced by businesses.","total household saving.","business taxes minus subsidies.","total exports."],exp:"Correct answer: the dollar value of total output produced by businesses."},
{id:"ex-g32",cat:"g",q:"A real estate agent earns a $5,000 commission for helping a family sell a 20-year-old house for $200,000. How much does this transaction add to current GDP?",opts:["$5,000","$205,000","$200,000","$0"],exp:"Resale of an old house is not counted. Only the $5,000 commission (a current service) is."},
{id:"ex-g33",cat:"g",q:"Which of the following is considered a \"service\" in the Personal Consumption (C) category?",opts:["A medical check-up at a hospital","A pair of running shoes","A bottle of mineral water","A laptop computer"],exp:"Correct answer: A medical check-up at a hospital"},
{id:"ex-g34",cat:"g",q:"If Nominal GDP in 2025 is $8,000 billion and Real GDP in 2025 is $8,000 billion, then 2025 is most likely:",opts:["the base year.","a recession year.","experiencing hyperinflation.","experiencing deflation."],exp:"Nominal GDP equals Real GDP only when current prices equal base-year prices, which is the base year."},
{id:"ex-g35",cat:"g",q:"Which of the following would cause Nominal GDP to increase while Real GDP decreases?",opts:["Output decreases by 3% and prices increase by 7%.","Output increases by 5% and prices decrease by 2%.","Output increases by 4% and prices remain constant.","Output decreases by 4% and prices decrease by 2%."],exp:"Correct answer: Output decreases by 3% and prices increase by 7%."},
{id:"ex-g36",cat:"g",q:"Depreciation (consumption of fixed capital) is the difference between:",opts:["Gross Domestic Product (GDP) and Net Domestic Product (NDP).","Nominal GDP and Real GDP.","Exports and Imports.","Personal Income and Disposable Income."],exp:"Correct answer: Gross Domestic Product (GDP) and Net Domestic Product (NDP)."},
{id:"ex-g37",cat:"g",q:"Which institution or group is NOT one of the four spending sectors in the GDP expenditure equation?",opts:["Commercial Banks (B)","Households (C)","Businesses (I)","Government (G)"],exp:"Correct answer: Commercial Banks (B)"},
{id:"ex-g38",cat:"g",q:"If a Thai citizen works as a software engineer in Singapore, their income is counted in:",opts:["Singapore's GDP.","Thailand's GDP.","neither country's GDP.","both countries' GDP."],exp:"Correct answer: Singapore's GDP."},
{id:"ex-g39",cat:"g",q:"Quality-of-life indicators used alongside GDP per capita to measure economic development include all of the following EXCEPT:",opts:["nominal interest rate.","life expectancy at birth.","infant mortality rate.","adult literacy rate."],exp:"Correct answer: nominal interest rate."},
{id:"ex-g40",cat:"g",q:"Suppose the GDP deflator increases from 120 in Year 1 to 126 in Year 2. What was the annual rate of inflation according to the GDP deflator?",opts:["5.0%","6.0%","4.76%","26.0%"],exp:"(126 − 120) ÷ 120 × 100 = 5.0%."},
{id:"ex-g41",cat:"g",q:"Which of the following is an example of a final good?",opts:["A loaf of bread sold to a household for dinner.","Steel sold to an automobile manufacturer.","Wood pulp sold to a paper mill.","Microchips sold to a smartphone assembler."],exp:"Correct answer: A loaf of bread sold to a household for dinner."},
{id:"ex-g42",cat:"g",q:"When calculating GDP, imports (M) are subtracted from exports (X) because:",opts:["spending on imports is already included in C, I, and G, and must be removed since imports were not produced domestically.","imports are illegal in most countries.","imports cause inflation.","exports are always smaller than imports."],exp:"Correct answer: spending on imports is already included in C, I, and G, and must be removed since imports were not produced domestically."},
{id:"ex-g43",cat:"g",q:"Which of the following is included in Government Consumption Expenditures and Gross Investment (G)?",opts:["Salaries paid to military personnel and construction of public schools.","Social security payments to retirees.","Welfare payments to low-income families.","Interest paid on the national debt."],exp:"Correct answer: Salaries paid to military personnel and construction of public schools."},
{id:"ex-g44",cat:"g",q:"In an economy, if inventories decline by $20 billion during the year while business fixed investment is $150 billion, what is Gross Private Domestic Investment (I)?",opts:["$130 billion","$170 billion","$150 billion","-$20 billion"],exp:"I = fixed investment + change in inventories = 150 + (−20) = 130."},
{id:"ex-g45",cat:"g",q:"Economic growth is most commonly measured as an increase in:",opts:["Real GDP or Real GDP per capita.","Nominal GDP.","the Consumer Price Index.","the national debt."],exp:"Correct answer: Real GDP or Real GDP per capita."},
{id:"ex-g46",cat:"g",q:"Five key determinants of long-run economic growth include natural resources, human resources, capital, technological progress, and:",opts:["a stable political and legal environment.","high inflation rates.","strict trade tariffs.","fixed exchange rates."],exp:"Correct answer: a stable political and legal environment."},
{id:"ex-g47",cat:"g",q:"If a bakery buys an industrial oven that lasts 10 years, this purchase is recorded in GDP under:",opts:["Gross Private Domestic Investment (I).","Personal Consumption (C).","Intermediate Goods.","Government Spending (G)."],exp:"A durable machine bought by a firm is fixed investment (I)."},
{id:"ex-g48",cat:"g",q:"Which of the following statements about Nominal GDP and Real GDP is TRUE?",opts:["In years prior to the base year, when prices were lower than in the base year, Real GDP is greater than Nominal GDP.","Real GDP can never exceed Nominal GDP.","Nominal GDP uses base-year prices and current-year quantities.","Real GDP uses current-year prices and base-year quantities."],exp:"Correct answer: In years prior to the base year, when prices were lower than in the base year, Real GDP is greater than Nominal GDP."},
{id:"ex-g49",cat:"g",q:"Value added by a firm is defined as:",opts:["the market value of a firm's output minus the value of intermediate inputs purchased from other firms.","total revenue minus total taxes.","total profit plus wages.","net exports divided by GDP."],exp:"Correct answer: the market value of a firm's output minus the value of intermediate inputs purchased from other firms."},
{id:"ex-g50",cat:"g",q:"Economic development differs from economic growth because economic development:",opts:["encompasses broader qualitative improvements in living standards, health, education, and institutional quality.","focuses strictly on increasing Nominal GDP.","ignores poverty and income inequality.","applies only to Industrially Advanced Countries (IACs)."],exp:"Correct answer: encompasses broader qualitative improvements in living standards, health, education, and institutional quality."},
{id:"ex-b1",cat:"b",q:"The four phases of a standard business cycle in sequential order are:",opts:["Peak, Recession, Trough, Recovery.","Peak, Recovery, Trough, Recession.","Trough, Recession, Peak, Recovery.","Recovery, Trough, Peak, Recession."],exp:"Correct answer: Peak, Recession, Trough, Recovery."},
{id:"ex-b2",cat:"b",q:"The phase of the business cycle that moves from a trough up to a peak is called:",opts:["recovery (expansion).","recession.","contraction.","depression."],exp:"Correct answer: recovery (expansion)."},
{id:"ex-b3",cat:"b",q:"A recession is traditionally defined as a period of declining Real GDP lasting for at least:",opts:["two consecutive quarters (six months).","one month.","one full calendar year.","ten consecutive quarters."],exp:"Correct answer: two consecutive quarters (six months)."},
{id:"ex-b4",cat:"b",q:"Which of the following individuals is officially counted as part of the Civilian Labor Force?",opts:["A 30-year-old who was laid off last month and actively applied for jobs last week.","A full-time university student who is not looking for work.","A retired 70-year-old receiving a pension.","A 14-year-old working part-time on a family farm."],exp:"Correct answer: A 30-year-old who was laid off last month and actively applied for jobs last week."},
{id:"ex-b5",cat:"b",q:"The unemployment rate is calculated as:",opts:["(Unemployed / Civilian Labor Force) × 100","(Unemployed / Total Population) × 100","(Civilian Labor Force / Employed) × 100","(Discouraged Workers / Civilian Labor Force) × 100"],exp:"Correct answer: (Unemployed / Civilian Labor Force) × 100"},
{id:"ex-b6",cat:"b",q:"Suppose a country has a total population of 100 million, a civilian noninstitutional population (age 16+) of 80 million, 57 million employed persons, and 3 million unemployed persons. What is the Civilian Labor Force?",opts:["60 million","100 million","80 million","57 million"],exp:"Labor force = employed + unemployed = 57 + 3 = 60 million."},
{id:"ex-b7",cat:"b",q:"Suppose a country has a total population of 100 million, a civilian noninstitutional population (age 16+) of 80 million, 57 million employed persons, and 3 million unemployed persons. What is the unemployment rate?",opts:["5.0%","3.0%","3.75%","5.26%"],exp:"Unemployment rate = 3 ÷ 60 × 100 = 5.0%."},
{id:"ex-b8",cat:"b",q:"Who are \"discouraged workers\"?",opts:["Unemployed individuals who have given up actively looking for work because they believe no jobs are available for them.","Workers who hate their current jobs.","Part-time workers who want full-time jobs.","Workers who are temporarily on strike."],exp:"Correct answer: Unemployed individuals who have given up actively looking for work because they believe no jobs are available for them."},
{id:"ex-b9",cat:"b",q:"Because discouraged workers are excluded from the civilian labor force, the official unemployment rate tends to:",opts:["understate the true extent of joblessness in the economy.","overstate the true extent of joblessness in the economy.","accurately reflect all people who want a job.","increase during an economic recovery when discouraged workers start looking for work again."],exp:"Correct answer: understate the true extent of joblessness in the economy."},
{id:"ex-b10",cat:"b",q:"Unemployment caused by the normal time it takes for workers to search for new jobs or transition between jobs is called:",opts:["frictional unemployment.","structural unemployment.","cyclical unemployment.","seasonal unemployment."],exp:"Correct answer: frictional unemployment."},
{id:"ex-b11",cat:"b",q:"Unemployment resulting from a mismatch between the skills workers possess and the skills demanded by employers (often due to technological change) is called:",opts:["structural unemployment.","frictional unemployment.","cyclical unemployment.","voluntary unemployment."],exp:"Correct answer: structural unemployment."},
{id:"ex-b12",cat:"b",q:"Unemployment directly caused by a downturn in the business cycle (a recession) is known as:",opts:["cyclical unemployment.","frictional unemployment.","structural unemployment.","natural unemployment."],exp:"Correct answer: cyclical unemployment."},
{id:"ex-b13",cat:"b",q:"Full employment in macroeconomics occurs when:",opts:["cyclical unemployment is zero, and only frictional and structural unemployment exist.","the unemployment rate is 0%.","frictional unemployment is zero.","everyone over the age of 16 has a full-time job."],exp:"Correct answer: cyclical unemployment is zero, and only frictional and structural unemployment exist."},
{id:"ex-b14",cat:"b",q:"The Natural Rate of Unemployment is equal to:",opts:["Frictional Unemployment + Structural Unemployment.","Frictional Unemployment + Cyclical Unemployment.","Structural Unemployment + Cyclical Unemployment.","0%."],exp:"Correct answer: Frictional Unemployment + Structural Unemployment."},
{id:"ex-b15",cat:"b",q:"A recent university graduate who turns down an immediate job offer to spend two months searching for a higher-paying position in her field is experiencing:",opts:["frictional unemployment.","cyclical unemployment.","structural unemployment.","discouraged worker status."],exp:"Correct answer: frictional unemployment."},
{id:"ex-b16",cat:"b",q:"A bank teller loses her job because customers increasingly use mobile banking apps and ATMs, and she lacks coding or digital skills. This is an example of:",opts:["structural unemployment.","frictional unemployment.","cyclical unemployment.","seasonal unemployment."],exp:"Correct answer: structural unemployment."},
{id:"ex-b17",cat:"b",q:"During a severe recession, an automobile manufacturer lays off 2,000 assembly line workers due to falling consumer demand for new cars. These workers are experiencing:",opts:["cyclical unemployment.","frictional unemployment.","structural unemployment.","natural unemployment."],exp:"Layoffs caused by falling demand in a recession are cyclical unemployment."},
{id:"ex-b18",cat:"b",q:"How does the official unemployment statistics treat a person who has a Ph.D. in engineering but can only find part-time work driving a ride-share vehicle for 10 hours a week?",opts:["Fully employed","Unemployed","Discouraged worker","Not in the labor force"],exp:"Anyone with even 1 paid hour a week counts as employed. Underemployment is not measured by the official rate."},
{id:"ex-b19",cat:"b",q:"Suppose 500,000 unemployed workers become discouraged and stop looking for work. Holding everything else constant, what happens to the official unemployment rate?",opts:["It decreases.","It increases.","It stays the same.","It becomes negative."],exp:"Discouraged workers leave the labor force, so the number of unemployed and the rate both fall (the rate looks better but is misleading)."},
{id:"ex-b20",cat:"b",q:"During the early stages of an economic recovery, the unemployment rate sometimes rises temporarily. Why does this happen?",opts:["Previously discouraged workers become optimistic, re-enter the labor force, and begin searching for jobs before being hired.","Firms immediately fire workers as sales increase.","Frictional unemployment disappears completely.","The government lowers the minimum wage."],exp:"Correct answer: Previously discouraged workers become optimistic, re-enter the labor force, and begin searching for jobs before being hired."},
{id:"ex-b21",cat:"b",q:"According to Keynesian economists, the primary cause of business cycle fluctuations is:",opts:["changes in aggregate expenditures: C + I + G + (X - M).","changes in sunspot activity.","rapid population growth.","constant money supply."],exp:"Correct answer: changes in aggregate expenditures: C + I + G + (X - M)."},
{id:"ex-b22",cat:"b",q:"Which sector of GDP tends to be the most volatile and fluctuates the most during business cycles?",opts:["Gross Private Domestic Investment (I)","Personal Consumption of nondurable goods","Government spending on education","Services consumption"],exp:"Correct answer: Gross Private Domestic Investment (I)"},
{id:"ex-b23",cat:"b",q:"The lowest point of real GDP at the end of a recession is called the:",opts:["trough.","peak.","expansion.","boom."],exp:"Correct answer: trough."},
{id:"ex-b24",cat:"b",q:"Which of the following people is NOT excluded from the civilian labor force?",opts:["Part-time retail workers working 15 hours per week","Active-duty military personnel","Full-time homemakers","Inmates in correctional institutions"],exp:"Correct answer: Part-time retail workers working 15 hours per week"},
{id:"ex-b25",cat:"b",q:"Underemployment occurs when:",opts:["workers are working jobs below their skill level or working part-time when they desire full-time work.","the unemployment rate falls below 2%.","firms hire too many workers.","workers refuse to accept minimum wage jobs."],exp:"Correct answer: workers are working jobs below their skill level or working part-time when they desire full-time work."},
{id:"ex-b26",cat:"b",q:"If the frictional unemployment rate is 2.5%, the structural unemployment rate is 2.0%, and the actual unemployment rate is 6.5%, what is the cyclical unemployment rate?",opts:["2.0%","4.5%","11.0%","0.5%"],exp:"Natural rate = 2.5 + 2.0 = 4.5%. Cyclical unemployment = 6.5 − 4.5 = 2.0%."},
{id:"ex-b27",cat:"b",q:"If the frictional unemployment rate is 2.5%, the structural unemployment rate is 2.0%, and the actual unemployment rate is 6.5%, what is the Natural Rate of Unemployment?",opts:["4.5%","6.5%","2.0%","2.5%"],exp:"Natural rate = frictional + structural = 2.5% + 2.0% = 4.5%."},
{id:"ex-b28",cat:"b",q:"The GDP Gap is defined as:",opts:["Potential Real GDP - Actual Real GDP.","Nominal GDP - Real GDP.","Exports - Imports.","Peak GDP - Trough GDP."],exp:"Correct answer: Potential Real GDP - Actual Real GDP."},
{id:"ex-b29",cat:"b",q:"When the actual unemployment rate exceeds the natural rate of unemployment:",opts:["there is a negative GDP gap (output is lost due to idle resources).","actual real GDP exceeds potential real GDP.","cyclical unemployment is negative.","the economy is at the peak of an inflationary boom."],exp:"Correct answer: there is a negative GDP gap (output is lost due to idle resources)."},
{id:"ex-b30",cat:"b",q:"According to Okun's Law, for every 1 percentage point that the actual unemployment rate exceeds the natural rate of unemployment, a negative GDP gap of about what percentage occurs?",opts:["2.0%","0.5%","1.0%","5.0%"],exp:"Correct answer: 2.0%"},
{id:"ex-b31",cat:"b",q:"Seasonal unemployment is best illustrated by:",opts:["a ski resort instructor losing his job in the summer.","an accountant laid off during a national financial crisis.","a coal miner replaced by automated machinery.","a software developer quitting to move to another city."],exp:"Correct answer: a ski resort instructor losing his job in the summer."},
{id:"ex-b32",cat:"b",q:"Which of the following government policies is most effective at reducing structural unemployment?",opts:["Funding job retraining programs and technical education.","Increasing government spending on highways.","Lowering interest rates.","Increasing unemployment insurance benefits."],exp:"Correct answer: Funding job retraining programs and technical education."},
{id:"ex-b33",cat:"b",q:"Why might generous unemployment insurance benefits slightly increase frictional unemployment?",opts:["They reduce the financial urgency for unemployed workers to accept the first job offer, allowing them to search longer.","They force businesses to shut down.","They eliminate structural mismatches.","They prevent workers from entering the labor force."],exp:"Correct answer: They reduce the financial urgency for unemployed workers to accept the first job offer, allowing them to search longer."},
{id:"ex-b34",cat:"b",q:"The labor force participation rate is calculated as:",opts:["(Civilian Labor Force / Civilian Noninstitutional Population age 16+) × 100","(Employed / Civilian Labor Force) × 100","(Unemployed / Total Population) × 100","(Civilian Labor Force / Total Population) × 100"],exp:"Correct answer: (Civilian Labor Force / Civilian Noninstitutional Population age 16+) × 100"},
{id:"ex-b35",cat:"b",q:"Suppose an economy has 140 million employed, 10 million unemployed, and 50 million adults (age 16+) not in the labor force. What is the Labor Force Participation Rate?",opts:["75%","70%","93.3%","6.67%"],exp:"Labor force = 140 + 10 = 150. Adults = 150 + 50 = 200. Participation rate = 150 ÷ 200 = 75%."},
{id:"ex-b36",cat:"b",q:"During the peak phase of a business cycle:",opts:["real GDP reaches a temporary maximum, and the economy is often near or beyond full employment with inflationary pressures.","unemployment is at its highest level.","business inventories accumulate rapidly due to falling sales.","interest rates fall to zero."],exp:"Correct answer: real GDP reaches a temporary maximum, and the economy is often near or beyond full employment with inflationary pressures."},
{id:"ex-b37",cat:"b",q:"A severe and prolonged recession, such as the one in the 1930s, is referred to as a:",opts:["depression.","stagnation.","deflation.","trough."],exp:"A very severe and prolonged recession is called a depression."},
{id:"ex-b38",cat:"b",q:"Which of the following is a criticism of official unemployment statistics?",opts:["False reporting by respondents claiming to look for work just to receive benefits can overstate unemployment.","They count discouraged workers as unemployed.","They exclude part-time workers from employment figures.","They include active-duty soldiers in the civilian labor force."],exp:"Correct answer: False reporting by respondents claiming to look for work just to receive benefits can overstate unemployment."},
{id:"ex-b39",cat:"b",q:"When an economy operates at its natural rate of unemployment:",opts:["real GDP is equal to potential GDP.","inflation is guaranteed to be 0%.","no one is looking for a job.","business cycles cease to exist."],exp:"Correct answer: real GDP is equal to potential GDP."},
{id:"ex-b40",cat:"b",q:"If the civilian labor force is 50 million and the unemployment rate is 6%, how many people are employed?",opts:["47 million","3 million","44 million","49.4 million"],exp:"Unemployed = 6% × 50 = 3 million. Employed = 50 − 3 = 47 million."},
{id:"ex-b41",cat:"b",q:"Non-economic costs of high cyclical unemployment include:",opts:["increased rates of depression, family stress, crime, and loss of self-respect.","higher corporate profits.","lower government budget deficits.","higher labor productivity."],exp:"Correct answer: increased rates of depression, family stress, crime, and loss of self-respect."},
{id:"ex-b42",cat:"b",q:"To be officially classified as \"unemployed,\" a person without a job must be:",opts:["available for work and have actively sought work within the past four weeks.","at least 21 years old.","receiving government welfare checks.","a former full-time employee."],exp:"Correct answer: available for work and have actively sought work within the past four weeks."},
{id:"ex-b43",cat:"b",q:"Globalization and outsourcing of manufacturing jobs to countries with lower labor costs primarily create which type of unemployment in the home country?",opts:["Structural","Frictional","Cyclical","Seasonal"],exp:"Correct answer: Structural"},
{id:"ex-b44",cat:"b",q:"Which of the following industries is most severely affected by a recession?",opts:["Durable goods manufacturing (e.g., automobiles, appliances) and construction","Healthcare and pharmaceuticals","Food and basic groceries","Public utilities (water and electricity)"],exp:"Correct answer: Durable goods manufacturing (e.g., automobiles, appliances) and construction"},
{id:"ex-b45",cat:"b",q:"Suppose 1 million workers are unemployed and 19 million are employed. If 500,000 currently unemployed workers find jobs, the unemployment rate drops from:",opts:["5.0% to 2.5%.","5.26% to 2.63%.","5.0% to 2.56%.","10.0% to 5.0%."],exp:"Before: 1 ÷ 20 = 5%. After: 0.5 ÷ 20 = 2.5% (the labor force stays at 20 million)."},
{id:"ex-b46",cat:"b",q:"A decrease in the demand for coal due to environmental regulations causes coal miners to lose their jobs. This is:",opts:["structural unemployment.","frictional unemployment.","cyclical unemployment.","seasonal unemployment."],exp:"Correct answer: structural unemployment."},
{id:"ex-b47",cat:"b",q:"Which of the following is a leading economic indicator that tends to change before the economy as a whole changes?",opts:["Stock market prices and building permits","The unemployment rate","Average duration of unemployment","Commercial loan defaults"],exp:"Correct answer: Stock market prices and building permits"},
{id:"ex-b48",cat:"b",q:"Can the actual unemployment rate ever fall below the natural rate of unemployment?",opts:["Yes, temporarily during an economic boom when firms hire overtime workers and marginal applicants.","No, because frictional unemployment can never change.","Yes, during a severe recession.","No, because potential GDP is an absolute physical ceiling."],exp:"Correct answer: Yes, temporarily during an economic boom when firms hire overtime workers and marginal applicants."},
{id:"ex-b49",cat:"b",q:"Which group typically experiences the highest unemployment rates during economic downturns?",opts:["Teenagers and low-skilled workers","College-educated professionals","Tenured university professors","Government civil servants"],exp:"Correct answer: Teenagers and low-skilled workers"},
{id:"ex-b50",cat:"b",q:"If total population is 200 million, under-16 population is 40 million, institutionalized population is 10 million, not in labor force is 50 million, and employed is 92 million, what is the unemployment rate?",opts:["8.0%","4.0%","5.33%","8.7%"],exp:"Population 16+ not institutionalized = 200 − 40 − 10 = 150. Labor force = 150 − 50 = 100. Unemployed = 100 − 92 = 8. Rate = 8%."},
{id:"ex-i1",cat:"i",q:"Inflation is defined as:",opts:["a sustained increase in the general (average) price level of goods and services in an economy.","an increase in the price of a single important commodity, such as oil.","a decrease in the purchasing power of goods.","a continuous rise in Real GDP."],exp:"Correct answer: a sustained increase in the general (average) price level of goods and services in an economy."},
{id:"ex-i2",cat:"i",q:"Deflation is defined as:",opts:["a decrease in the general price level of goods and services.","a slowdown in the rate of inflation.","a rise in interest rates.","a decline in Real GDP."],exp:"Correct answer: a decrease in the general price level of goods and services."},
{id:"ex-i3",cat:"i",q:"The Consumer Price Index (CPI) measures changes in the average prices of:",opts:["a fixed market basket of consumer goods and services purchased by typical urban households.","all final goods and services produced domestically.","raw materials and wholesale industrial inputs only.","imported capital goods."],exp:"Correct answer: a fixed market basket of consumer goods and services purchased by typical urban households."},
{id:"ex-i4",cat:"i",q:"In the base year, the Consumer Price Index (CPI) is always equal to:",opts:["100","0","1","1,000"],exp:"Correct answer: 100"},
{id:"ex-i5",cat:"i",q:"Suppose the cost of a fixed market basket of goods was $500 in the base year (2020) and is $575 in 2026. What is the CPI in 2026?",opts:["115","75","86.9","175"],exp:"CPI = 575 ÷ 500 × 100 = 115."},
{id:"ex-i6",cat:"i",q:"If the CPI rises from 200 in Year 1 to 210 in Year 2, what is the annual rate of inflation in Year 2?",opts:["5%","10%","4.76%","210%"],exp:"(210 − 200) ÷ 200 × 100 = 5%."},
{id:"ex-i7",cat:"i",q:"Real Income is calculated using which formula?",opts:["(Nominal Income / CPI) × 100","Nominal Income × CPI","(CPI / Nominal Income) × 100","Nominal Income - CPI"],exp:"Correct answer: (Nominal Income / CPI) × 100"},
{id:"ex-i8",cat:"i",q:"Suppose your nominal salary increases from $40,000 to $42,000, while the CPI rises from 100 to 108. What happened to your real income (purchasing power)?",opts:["It decreased because prices rose faster than your nominal income.","It increased by 5%.","It stayed exactly the same.","It increased by 8%."],exp:"Real income = 42,000 ÷ 1.08 ≈ 38,889, below 40,000. Pay rose 5% but prices rose 8%."},
{id:"ex-i9",cat:"i",q:"What is \"substitution bias\" in the calculation of the CPI?",opts:["The CPI ignores the fact that consumers substitute away from goods whose relative prices have risen toward cheaper alternatives.","The CPI substitutes imported goods for domestic goods every month.","Producers substitute cheap labor for expensive capital.","The government substitutes new base years every year."],exp:"Correct answer: The CPI ignores the fact that consumers substitute away from goods whose relative prices have risen toward cheaper alternatives."},
{id:"ex-i10",cat:"i",q:"Because of substitution bias and unmeasured quality improvements, economists generally believe the CPI:",opts:["overstates the true increase in the cost of living.","understates the true rate of inflation.","is completely accurate to the decimal point.","only measures deflation."],exp:"Correct answer: overstates the true increase in the cost of living."},
{id:"ex-i11",cat:"i",q:"Inflation caused by excessive aggregate spending (\"too much money chasing too few goods\") when the economy is near full employment is called:",opts:["demand-pull inflation.","cost-push inflation.","stagflation.","hyperinflation."],exp:"Correct answer: demand-pull inflation."},
{id:"ex-i12",cat:"i",q:"Inflation caused by rising per-unit production costs, such as a sharp spike in crude oil prices or aggressive wage hikes, is called:",opts:["cost-push inflation.","demand-pull inflation.","disinflation.","core inflation."],exp:"Correct answer: cost-push inflation."},
{id:"ex-i13",cat:"i",q:"Extremely rapid, out-of-control inflation—often exceeding 50% per month—that destroys the value of a nation's currency is called:",opts:["hyperinflation.","creeping inflation.","disinflation.","deflation."],exp:"Hyperinflation is extremely rapid inflation, often above 50% per month."},
{id:"ex-i14",cat:"i",q:"During a period of hyperinflation, how do consumers typically behave?",opts:["They spend their money immediately on real goods and foreign currencies before prices rise further.","They save as much cash as possible in low-interest bank accounts.","They lend money to friends at fixed zero-percent interest rates.","They delay all purchases until next year."],exp:"Correct answer: They spend their money immediately on real goods and foreign currencies before prices rise further."},
{id:"ex-i15",cat:"i",q:"How does the CPI differ from the GDP Deflator?",opts:["The CPI includes imported consumer goods and uses a fixed basket, whereas the GDP deflator covers all domestically produced goods and services using current output weights.","The CPI includes capital goods, while the GDP deflator does not.","The GDP deflator is always 100.","The CPI measures producer prices only."],exp:"Correct answer: The CPI includes imported consumer goods and uses a fixed basket, whereas the GDP deflator covers all domestically produced goods and services using current output weights."},
{id:"ex-i16",cat:"i",q:"Who is HURT by unanticipated inflation?",opts:["Savers holding cash and retirees living on fixed nominal pensions.","Borrowers repaying loans with fixed interest rates.","Owners of real estate and gold.","Governments with large fixed-rate nominal debts."],exp:"Correct answer: Savers holding cash and retirees living on fixed nominal pensions."},
{id:"ex-i17",cat:"i",q:"Who BENEFITS from unanticipated inflation?",opts:["Borrowers (debtors) who repay loans with dollars that have lower purchasing power.","Lenders (creditors) who issued fixed-rate mortgages.","Workers whose wages are fixed by a multi-year contract without a cost-of-living adjustment.","People holding cash under their mattresses."],exp:"Correct answer: Borrowers (debtors) who repay loans with dollars that have lower purchasing power."},
{id:"ex-i18",cat:"i",q:"Suppose a bank wants to earn a real interest rate of 4% on a loan, and it expects the inflation rate to be 3% over the next year. What nominal interest rate should the bank charge?",opts:["7%","1%","4%","12%"],exp:"Nominal rate ≈ real rate + expected inflation = 4% + 3% = 7%."},
{id:"ex-i19",cat:"i",q:"The Fisher Equation states that the real interest rate is approximately equal to:",opts:["Nominal Interest Rate - Inflation Rate.","Nominal Interest Rate + Inflation Rate.","Inflation Rate - Nominal Interest Rate.","Nominal Interest Rate × Inflation Rate."],exp:"Correct answer: Nominal Interest Rate - Inflation Rate."},
{id:"ex-i20",cat:"i",q:"What is \"disinflation\"?",opts:["A reduction in the rate of inflation (e.g., inflation slowing from 6% to 2%, while prices still rise).","A decrease in the general price level (negative inflation).","Inflation excluded from food and energy prices.","Inflation caused by government deficits."],exp:"Correct answer: A reduction in the rate of inflation (e.g., inflation slowing from 6% to 2%, while prices still rise)."},
{id:"ex-i21",cat:"i",q:"Cost-of-Living Adjustments (COLAs) are clauses in labor contracts or pension plans that:",opts:["automatically tie wage or benefit increases to increases in the CPI.","freeze wages during a recession.","reduce taxes for corporations.","penalize workers for tardiness."],exp:"Correct answer: automatically tie wage or benefit increases to increases in the CPI."},
{id:"ex-i22",cat:"i",q:"In 1980, a movie ticket cost $2.50 when the CPI was 82.4. In 2025, the CPI is 310.0. What is the equivalent price of that 1980 movie ticket in 2025 dollars?",opts:["$9.41","$0.66","$7.75","$11.20"],exp:"2.50 × 310.0 ÷ 82.4 ≈ $9.41."},
{id:"ex-i23",cat:"i",q:"\"Menu costs\" of inflation refer to:",opts:["the real resources firms must spend to constantly update price lists, catalogs, websites, and labels.","the rising price of restaurant meals.","the cost of printing new paper currency by the central bank.","higher taxes paid on nominal capital gains."],exp:"Correct answer: the real resources firms must spend to constantly update price lists, catalogs, websites, and labels."},
{id:"ex-i24",cat:"i",q:"\"Shoe-leather costs\" of inflation refer to:",opts:["the wasted time and effort people spend making frequent trips to the bank to minimize their cash holdings.","the rising cost of footwear manufacturing.","the cost of importing leather goods.","the loss of export competitiveness."],exp:"Correct answer: the wasted time and effort people spend making frequent trips to the bank to minimize their cash holdings."},
{id:"ex-i25",cat:"i",q:"Core inflation is measured by excluding which two volatile components from the CPI?",opts:["Food and energy","Housing and healthcare","Clothing and education","Transportation and entertainment"],exp:"Correct answer: Food and energy"},
{id:"ex-i26",cat:"i",q:"Suppose a market basket consists of 10 units of Good A and 5 units of Good B. In the base year, Good A costs $2 and Good B costs $4. In the current year, Good A costs $3 and Good B costs $6. What is the CPI in the current year?",opts:["150","120","60","40"],exp:"Base basket = 10 × 2 + 5 × 4 = 40. Current basket = 10 × 3 + 5 × 6 = 60. CPI = 60 ÷ 40 × 100 = 150."},
{id:"ex-i27",cat:"i",q:"Why does the CPI have difficulty accounting for \"quality changes and new goods\"?",opts:["When a product's price rises because of improved features and higher quality, the CPI may mistakenly record it purely as inflation rather than greater value.","Because the government refuses to survey electronics stores.","Because consumers never buy new products.","Because quality always deteriorates over time."],exp:"Correct answer: When a product's price rises because of improved features and higher quality, the CPI may mistakenly record it purely as inflation rather than greater value."},
{id:"ex-i28",cat:"i",q:"If your nominal income rises by 10% and the CPI rises by 10%, your real income:",opts:["remains unchanged.","increases by 10%.","decreases by 10%.","increases by 20%."],exp:"Real income growth ≈ nominal growth − inflation = 10% − 10% = 0."},
{id:"ex-i29",cat:"i",q:"Hyperinflation is almost always caused by:",opts:["excessive growth in the money supply by a government printing money to finance huge budget deficits.","labor unions demanding higher wages.","cold weather ruining agricultural harvests.","consumers saving too much money."],exp:"Correct answer: excessive growth in the money supply by a government printing money to finance huge budget deficits."},
{id:"ex-i30",cat:"i",q:"If the CPI was 150 in 2023, 156 in 2024, and 163.8 in 2025, what were the inflation rates in 2024 and 2025 respectively?",opts:["4.0% and 5.0%","6.0% and 7.8%","4.0% and 4.0%","56.0% and 63.8%"],exp:"2024: (156 − 150) ÷ 150 = 4%. 2025: (163.8 − 156) ÷ 156 = 5%."},
{id:"ex-i31",cat:"i",q:"A negative inflation rate (e.g., -2%) indicates that the economy is experiencing:",opts:["deflation.","hyperinflation.","disinflation.","demand-pull inflation."],exp:"A negative inflation rate means the price level is falling: deflation."},
{id:"ex-i32",cat:"i",q:"Why do central banks fear deflation just as much as high inflation?",opts:["Consumers delay purchases expecting even lower prices in the future, causing spending to collapse, debts to become heavier in real terms, and unemployment to soar.","Deflation makes exports too cheap.","Deflation causes hyperinflation the following month.","Deflation increases nominal wages automatically."],exp:"Correct answer: Consumers delay purchases expecting even lower prices in the future, causing spending to collapse, debts to become heavier in real terms, and unemployment to soar."},
{id:"ex-i33",cat:"i",q:"If the nominal interest rate is 5% and the actual inflation rate turns out to be 6%, the real interest rate is:",opts:["-1%","+11%","+1%","0%"],exp:"Real rate = nominal rate − inflation = 5% − 6% = −1%."},
{id:"ex-i34",cat:"i",q:"Which government agency in the United States calculates and publishes the CPI?",opts:["The Bureau of Labor Statistics (BLS)","The Federal Reserve","The Internal Revenue Service (IRS)","The Department of Defense"],exp:"Correct answer: The Bureau of Labor Statistics (BLS)"},
{id:"ex-i35",cat:"i",q:"The Producer Price Index (PPI) is often watched by economists as an early warning sign of consumer inflation because:",opts:["increases in wholesale and raw material prices paid by producers are eventually passed on to consumers in retail prices.","it measures stock market prices.","it includes imported luxury yachts.","it is always higher than the CPI."],exp:"Correct answer: increases in wholesale and raw material prices paid by producers are eventually passed on to consumers in retail prices."},
{id:"ex-i36",cat:"i",q:"Maria earned $50,000 in Year 1 when the CPI was 125. In Year 2, the CPI rose to 130. What nominal salary must Maria earn in Year 2 just to maintain the exact same real income?",opts:["$52,000","$50,500","$52,500","$55,000"],exp:"Needed salary = 50,000 × 130 ÷ 125 = 52,000."},
{id:"ex-i37",cat:"i",q:"Which of the following is an example of a \"supply shock\" that triggers cost-push inflation?",opts:["A major war in the Middle East disrupting global crude oil supplies.","A sudden spike in consumer confidence.","A large government tax cut for households.","A boom in housing construction."],exp:"Correct answer: A major war in the Middle East disrupting global crude oil supplies."},
{id:"ex-i38",cat:"i",q:"\"Bracket creep\" occurs during inflation when:",opts:["rising nominal incomes push taxpayers into higher progressive income tax brackets even though their real purchasing power has not increased.","businesses raise prices in secret.","workers demand higher pensions.","banks lower savings account interest rates."],exp:"Correct answer: rising nominal incomes push taxpayers into higher progressive income tax brackets even though their real purchasing power has not increased."},
{id:"ex-i39",cat:"i",q:"When inflation is fully anticipated by both borrowers and lenders, its redistributive harm is:",opts:["largely avoided, because lenders incorporate an inflation premium into nominal interest rates.","maximized.","doubled.","shifted entirely to the government."],exp:"Correct answer: largely avoided, because lenders incorporate an inflation premium into nominal interest rates."},
{id:"ex-i40",cat:"i",q:"Suppose an economy's CPI basket weights are 50% Housing, 30% Food, and 20% Transportation. If Housing prices rise by 10%, Food prices rise by 5%, and Transportation prices fall by 5%, what is the overall inflation rate?",opts:["5.5%","10.0%","3.33%","7.5%"],exp:"0.5 × 10% + 0.3 × 5% + 0.2 × (−5%) = 5 + 1.5 − 1 = 5.5%."},
{id:"ex-i41",cat:"i",q:"Which demographic group might find that the standard CPI understates their personal cost-of-living increases?",opts:["Elderly retirees who spend a much larger share of their income on rapidly inflating healthcare and medical services.","College students who buy mostly electronics.","Young professionals who rent apartments.","Farmers who grow their own food."],exp:"Correct answer: Elderly retirees who spend a much larger share of their income on rapidly inflating healthcare and medical services."},
{id:"ex-i42",cat:"i",q:"A wage-price spiral happens when:",opts:["rising prices prompt workers to demand higher nominal wages, which raises business costs and forces firms to raise prices even further.","lower wages lead to lower prices.","imports replace domestic goods.","interest rates fall to zero."],exp:"Correct answer: rising prices prompt workers to demand higher nominal wages, which raises business costs and forces firms to raise prices even further."},
{id:"ex-i43",cat:"i",q:"If Real GDP is growing at 3% and the money supply grows at 15%, classical monetary theory predicts:",opts:["substantial inflation.","deflation.","rising unemployment.","falling nominal GDP."],exp:"Money grows much faster than real output (15% vs 3%), so prices are pushed up: substantial inflation."},
{id:"ex-i44",cat:"i",q:"Which of the following assets generally protects an investor best against unexpected inflation?",opts:["Real estate, commodities, or inflation-indexed bonds (TIPS)","Cash stored in a safe","Fixed-rate long-term government bonds","A fixed-dollar life insurance policy"],exp:"Correct answer: Real estate, commodities, or inflation-indexed bonds (TIPS)"},
{id:"ex-i45",cat:"i",q:"In 2020 (Base Year), Nominal GDP was $1,000 billion. In 2025, Nominal GDP is $1,320 billion and Real GDP is $1,100 billion. What is the cumulative inflation rate between 2020 and 2025 based on the GDP deflator?",opts:["20%","32%","10%","12%"],exp:"GDP deflator in 2025 = 1,320 ÷ 1,100 × 100 = 120. Prices rose 20% since 2020 (deflator 100)."},
{id:"ex-i46",cat:"i",q:"During the German hyperinflation of 1923, workers were often paid twice a day because:",opts:["prices rose so fast by the hour that wages earned in the morning lost half their purchasing power by evening.","banks closed at noon.","labor unions outlawed weekly paychecks.","coins were too heavy to carry."],exp:"Prices rose so fast that wages lost value within hours."},
{id:"ex-i47",cat:"i",q:"Inflation reduces the value of money as a:",opts:["store of value.","medium of exchange only.","unit of measurement for weight.","factor of production."],exp:"Correct answer: store of value."},
{id:"ex-i48",cat:"i",q:"Which of the following events would most likely cause demand-pull inflation?",opts:["A massive increase in government military spending when factories are already operating at full capacity.","A nationwide drought destroying corn and wheat crops.","A sharp increase in corporate income taxes.","A collapse in the stock market."],exp:"Correct answer: A massive increase in government military spending when factories are already operating at full capacity."},
{id:"ex-i49",cat:"i",q:"If the CPI rises from 100 to 200, the purchasing power of $1 has:",opts:["been cut in half (fallen by 50%).","doubled.","fallen by 100%.","remained unchanged."],exp:"Prices doubled, so $1 buys half as much."},
{id:"ex-i50",cat:"i",q:"Suppose nominal wages rise by 4%, labor productivity rises by 3%, and the inflation rate is 2%. What happened to real wages?",opts:["Real wages rose by 2%.","Real wages fell by 1%.","Real wages rose by 6%.","Real wages rose by 1%."],exp:"Real wage change ≈ nominal wage change − inflation = 4% − 2% = +2%. Productivity is a distractor."},
{id:"ex-a1",cat:"a",q:"The Aggregate Demand (AD) curve shows the relationship between the general price level (CPI) and:",opts:["the total quantity of Real GDP demanded by households, businesses, government, and foreigners.","the quantity of a single good demanded.","the unemployment rate.","the money supply."],exp:"Correct answer: the total quantity of Real GDP demanded by households, businesses, government, and foreigners."},
{id:"ex-a2",cat:"a",q:"The Aggregate Demand (AD) curve slopes downward from left to right because of three effects: the real balances effect, the interest rate effect, and the:",opts:["foreign purchases (net exports) effect.","income effect.","diminishing marginal utility effect.","substitution effect."],exp:"Correct answer: foreign purchases (net exports) effect."},
{id:"ex-a3",cat:"a",q:"According to the \"real balances effect\" (wealth effect), when the general price level rises:",opts:["the real purchasing power of people's cash and savings falls, causing them to reduce consumption spending (C).","people feel wealthier and buy more luxury goods.","interest rates fall.","exports become cheaper."],exp:"Correct answer: the real purchasing power of people's cash and savings falls, causing them to reduce consumption spending (C)."},
{id:"ex-a4",cat:"a",q:"According to the \"interest rate effect,\" a higher general price level increases the demand for money, which drives up interest rates and consequently reduces:",opts:["business investment (I) and interest-sensitive consumer spending.","government transfer payments.","income tax rates.","the natural rate of unemployment."],exp:"Correct answer: business investment (I) and interest-sensitive consumer spending."},
{id:"ex-a5",cat:"a",q:"According to the \"foreign purchases effect,\" if the domestic price level in Thailand rises relative to foreign price levels:",opts:["Thai exports become more expensive to foreigners and imports become cheaper for Thais, reducing Net Exports (X - M).","Thai exports surge and imports fall.","the Thai Baht automatically appreciates.","foreign tourists visit Thailand in record numbers."],exp:"Correct answer: Thai exports become more expensive to foreigners and imports become cheaper for Thais, reducing Net Exports (X - M)."},
{id:"ex-a6",cat:"a",q:"A change in the general price level causes:",opts:["a movement along a stationary AD curve.","a rightward shift of the AD curve.","a leftward shift of the AD curve.","a vertical shift of the AS curve."],exp:"Correct answer: a movement along a stationary AD curve."},
{id:"ex-a7",cat:"a",q:"Which of the following will shift the Aggregate Demand (AD) curve to the RIGHT?",opts:["An increase in business optimism and expected future profits, boosting Investment (I).","A decrease in consumer confidence.","An increase in personal income taxes.","A recession in major foreign trading partners."],exp:"Correct answer: An increase in business optimism and expected future profits, boosting Investment (I)."},
{id:"ex-a8",cat:"a",q:"Which of the following will shift the Aggregate Demand (AD) curve to the LEFT?",opts:["A sharp decline in stock market and housing prices, reducing household wealth.","An increase in government infrastructure spending (G).","A depreciation of the domestic currency.","Lower interest rates set by the central bank."],exp:"Correct answer: A sharp decline in stock market and housing prices, reducing household wealth."},
{id:"ex-a9",cat:"a",q:"The Aggregate Supply (AS) curve shows the relationship between the general price level and:",opts:["the quantity of Real GDP supplied (produced) by domestic firms.","the total amount of taxes collected.","household saving.","the trade deficit."],exp:"Correct answer: the quantity of Real GDP supplied (produced) by domestic firms."},
{id:"ex-a10",cat:"a",q:"In the Keynesian view, the Aggregate Supply (AS) curve is horizontal (flat) during a deep recession because:",opts:["there is substantial idle capacity and unemployed labor, and wages/prices are \"sticky\" downward, so output can expand without raising prices.","wages and prices are flexible downward.","the economy is already at full employment.","firms refuse to hire new workers."],exp:"Correct answer: there is substantial idle capacity and unemployed labor, and wages/prices are \"sticky\" downward, so output can expand without raising prices."},
{id:"ex-a11",cat:"a",q:"Which famous economist argued that \"demand creates its own supply\" during a recession and advocated for active government intervention to boost AD?",opts:["John Maynard Keynes","Adam Smith","Milton Friedman","David Ricardo"],exp:"Correct answer: John Maynard Keynes"},
{id:"ex-a12",cat:"a",q:"In the Classical view, the long-run Aggregate Supply (LRAS) curve is:",opts:["vertical at the full-employment level of Real GDP (potential GDP).","horizontal at the current price level.","downward sloping.","upward sloping at a 45-degree angle."],exp:"Correct answer: vertical at the full-employment level of Real GDP (potential GDP)."},
{id:"ex-a13",cat:"a",q:"Classical economists believe that the economy is self-correcting in the long run because:",opts:["wages and prices are fully flexible both upward and downward.","the government always balances its budget.","central banks print money continuously.","consumers never change their spending habits."],exp:"Correct answer: wages and prices are fully flexible both upward and downward."},
{id:"ex-a14",cat:"a",q:"In the intermediate (upward-sloping) range of the Aggregate Supply curve, a rightward shift in Aggregate Demand (AD) results in:",opts:["higher Real GDP and a higher price level (demand-pull inflation).","higher Real GDP and a lower price level.","lower Real GDP and a higher price level.","no change in Real GDP."],exp:"Correct answer: higher Real GDP and a higher price level (demand-pull inflation)."},
{id:"ex-a15",cat:"a",q:"What is \"stagflation\"?",opts:["High inflation occurring simultaneously with stagnant or falling Real GDP and rising unemployment.","Rapid economic growth combined with falling prices.","Zero inflation and zero unemployment.","A trade surplus combined with a budget surplus."],exp:"Correct answer: High inflation occurring simultaneously with stagnant or falling Real GDP and rising unemployment."},
{id:"ex-a16",cat:"a",q:"Stagflation (high inflation with falling Real GDP) is caused by a:",opts:["leftward shift of the Short-Run Aggregate Supply (SRAS) curve due to a negative supply shock (e.g., soaring oil prices).","rightward shift of the AD curve.","leftward shift of the AD curve.","rightward shift of the SRAS curve."],exp:"Correct answer: leftward shift of the Short-Run Aggregate Supply (SRAS) curve due to a negative supply shock (e.g., soaring oil prices)."},
{id:"ex-a17",cat:"a",q:"Which of the following will shift the Aggregate Supply (AS) curve to the RIGHT?",opts:["A major technological breakthrough that increases labor productivity and lowers per-unit production costs.","A sharp increase in nominal wage rates.","Higher corporate taxes and stricter environmental regulations.","A quadrupling of imported crude oil prices."],exp:"Correct answer: A major technological breakthrough that increases labor productivity and lowers per-unit production costs."},
{id:"ex-a18",cat:"a",q:"Which of the following will shift the Short-Run Aggregate Supply (SRAS) curve to the LEFT?",opts:["A widespread increase in raw material and energy costs.","A decrease in business taxes.","An increase in immigration of skilled workers.","Falling interest rates."],exp:"Correct answer: A widespread increase in raw material and energy costs."},
{id:"ex-a19",cat:"a",q:"Suppose an economy is initially in long-run equilibrium at full employment. If Aggregate Demand suddenly decreases due to a collapse in business investment, what happens in the short run?",opts:["Real GDP falls below potential GDP, unemployment rises, and the price level falls (or rises more slowly).","Real GDP rises above potential GDP and prices soar.","Both Real GDP and the price level remain unchanged.","The LRAS curve shifts to the left."],exp:"Correct answer: Real GDP falls below potential GDP, unemployment rises, and the price level falls (or rises more slowly)."},
{id:"ex-a20",cat:"a",q:"Suppose an economy is initially in long-run equilibrium at full employment, and Aggregate Demand suddenly decreases due to a collapse in business investment, leaving unemployment high. According to the Classical self-correction mechanism, how does the economy return to full employment in the long run without government intervention?",opts:["High unemployment eventually forces nominal wages and input prices downward, shifting the SRAS curve to the right until potential GDP is restored at a lower price level.","Consumers suddenly double their spending for no reason.","The LRAS curve shifts left to meet the lower AD curve.","Interest rates rise to 20%."],exp:"Classical view: in a slump, wages and prices fall, shifting SRAS right until full employment returns at a lower price level."},
{id:"ex-a21",cat:"a",q:"In the Keynesian range (horizontal AS), an increase in Aggregate Demand will:",opts:["increase Real GDP without causing inflation.","cause severe inflation without increasing Real GDP.","reduce Real GDP.","shift the LRAS curve left."],exp:"Correct answer: increase Real GDP without causing inflation."},
{id:"ex-a22",cat:"a",q:"In the Classical range (vertical AS at full employment), an increase in Aggregate Demand will:",opts:["raise the general price level (pure demand-pull inflation) with no lasting increase in Real GDP.","increase Real GDP substantially.","lower the unemployment rate permanently to 0%.","cause deflation."],exp:"Correct answer: raise the general price level (pure demand-pull inflation) with no lasting increase in Real GDP."},
{id:"ex-a23",cat:"a",q:"Say's Law, associated with Classical economics, states that:",opts:["\"supply creates its own demand.\"","\"demand creates its own supply.\"","\"inflation is always and everywhere a monetary phenomenon.\"","\"bad money drives out good.\""],exp:"Correct answer: \"supply creates its own demand.\""},
{id:"ex-a24",cat:"a",q:"Why are nominal wages often \"sticky\" downward in the short run?",opts:["Multi-year labor union contracts, minimum wage laws, and fears of hurting worker morale prevent firms from easily cutting wages.","Workers love taking pay cuts.","Prices fall faster than wages rise.","The government sets all wages daily."],exp:"Correct answer: Multi-year labor union contracts, minimum wage laws, and fears of hurting worker morale prevent firms from easily cutting wages."},
{id:"ex-a25",cat:"a",q:"If the Thai Baht depreciates significantly against the U.S. Dollar, what happens to Thailand's Aggregate Demand curve?",opts:["AD shifts right because Thai exports become cheaper to foreigners and imports become more expensive, increasing Net Exports (X - M).","AD shifts left because imports become cheaper.","AD does not shift; only AS shifts.","AD becomes completely vertical."],exp:"Correct answer: AD shifts right because Thai exports become cheaper to foreigners and imports become more expensive, increasing Net Exports (X - M)."},
{id:"ex-a26",cat:"a",q:"Suppose an economy is experiencing a recessionary gap (actual Real GDP is less than potential Real GDP). Which combination of shifts would restore full employment while keeping the price level relatively stable?",opts:["AD shifts right and AS shifts right.","AD shifts left and AS shifts left.","AD shifts left and AS shifts right.","AD shifts right and AS shifts left."],exp:"Correct answer: AD shifts right and AS shifts right."},
{id:"ex-a27",cat:"a",q:"An increase in business subsidies paid by the government to domestic manufacturers will:",opts:["lower production costs and shift the AS curve to the right.","shift the AD curve left.","cause stagflation.","shift the LRAS curve left."],exp:"Correct answer: lower production costs and shift the AS curve to the right."},
{id:"ex-a28",cat:"a",q:"Macroeconomic equilibrium occurs at the intersection of:",opts:["the Aggregate Demand (AD) curve and the Aggregate Supply (AS) curve.","the individual demand and supply curves for wheat.","the consumption function and the tax rate.","exports and imports."],exp:"Correct answer: the Aggregate Demand (AD) curve and the Aggregate Supply (AS) curve."},
{id:"ex-a29",cat:"a",q:"What shifts the Long-Run Aggregate Supply (LRAS) curve to the right?",opts:["Increases in the quantity and quality of resources (capital, labor, education) and technological innovation.","A temporary cut in interest rates.","An increase in the money supply.","Higher consumer confidence."],exp:"Correct answer: Increases in the quantity and quality of resources (capital, labor, education) and technological innovation."},
{id:"ex-a30",cat:"a",q:"A rightward shift of the LRAS curve is graphically identical to:",opts:["an outward shift of the Production Possibilities Curve (PPC), representing economic growth.","an inward shift of the Production Possibilities Curve (PPC).","a movement along the PPC.","a recession."],exp:"Correct answer: an outward shift of the Production Possibilities Curve (PPC), representing economic growth."},
{id:"ex-a31",cat:"a",q:"Why is stagflation particularly difficult for policymakers using traditional AD-management policies (like fiscal or monetary stimulus)?",opts:["Boosting AD to cure the recession worsens inflation, whereas reducing AD to fight inflation worsens the recession and unemployment.","Fiscal policy has no effect on AD.","Stagflation only lasts for one week.","Central banks are forbidden from acting during stagflation."],exp:"Correct answer: Boosting AD to cure the recession worsens inflation, whereas reducing AD to fight inflation worsens the recession and unemployment."},
{id:"ex-a32",cat:"a",q:"If households expect their future incomes to fall sharply next year due to an upcoming economic slowdown, what happens today?",opts:["Current consumption (C) falls, shifting AD to the left.","Current consumption (C) rises, shifting AD to the right.","AS shifts to the right.","Net exports increase immediately."],exp:"Correct answer: Current consumption (C) falls, shifting AD to the left."},
{id:"ex-a33",cat:"a",q:"A decrease in the personal income tax rate primarily affects the macroeconomy initially by:",opts:["increasing household disposable income, boosting consumption (C), and shifting AD to the right.","reducing government spending (G) automatically.","shifting LRAS to the left.","increasing the natural rate of unemployment."],exp:"Correct answer: increasing household disposable income, boosting consumption (C), and shifting AD to the right."},
{id:"ex-a34",cat:"a",q:"Which of the following is NOT a nonprice-level determinant of Aggregate Demand?",opts:["Input prices and resource productivity","Consumer wealth and expectations","Interest rates and business investment","Foreign incomes and exchange rates"],exp:"Correct answer: Input prices and resource productivity"},
{id:"ex-a35",cat:"a",q:"Suppose a major hurricane destroys oil refineries and power plants across a country's industrial coast. In the AD-AS model, this causes:",opts:["SRAS to shift left, resulting in higher prices and lower Real GDP.","AD to shift right.","SRAS to shift right.","LRAS to shift right."],exp:"Correct answer: SRAS to shift left, resulting in higher prices and lower Real GDP."},
{id:"ex-a36",cat:"a",q:"In an economy with an upward-sloping SRAS curve, suppose AD shifts right by $100 billion, but because the price level rises, equilibrium Real GDP increases by only $60 billion. This illustrates that:",opts:["the multiplier effect is completely dampened (partially offset) by rising prices.","the economy is in a Keynesian liquidity trap.","the AS curve is vertical.","imports fell to zero."],exp:"Part of the AD increase is absorbed by higher prices, so Real GDP rises by less than the AD shift."},
{id:"ex-a37",cat:"a",q:"If China and the United States (Thailand's largest trading partners) experience rapid economic growth, what is the effect on Thailand's AD-AS model?",opts:["Thailand's AD shifts right as foreign demand for Thai exports rises.","Thailand's AD shifts left as exports fall.","Thailand's SRAS shifts left.","Thailand's LRAS shifts left."],exp:"Correct answer: Thailand's AD shifts right as foreign demand for Thai exports rises."},
{id:"ex-a38",cat:"a",q:"\"Ratchet effect\" in the AD-AS model refers to the observation that:",opts:["prices rise easily when AD increases, but prices are inflexible downward when AD decreases.","unemployment falls faster than it rises.","taxes never go down.","imports always exceed exports."],exp:"Correct answer: prices rise easily when AD increases, but prices are inflexible downward when AD decreases."},
{id:"ex-a39",cat:"a",q:"When Actual Real GDP exceeds Potential Real GDP (an inflationary gap):",opts:["the unemployment rate is below the natural rate of unemployment.","the unemployment rate is above the natural rate of unemployment.","the economy is in a severe depression.","prices are falling rapidly."],exp:"Correct answer: the unemployment rate is below the natural rate of unemployment."},
{id:"ex-a40",cat:"a",q:"Suppose an economy is at full employment. A sudden boom in consumer spending shifts AD right, creating an inflationary gap. In the long run, without government intervention, how does the economy self-correct?",opts:["Tight labor markets push nominal wages up, shifting SRAS left until Real GDP returns to potential GDP at a permanently higher price level.","SRAS shifts right, lowering prices back to the original level.","AD automatically shifts back to the left.","Potential GDP increases to match the higher AD."],exp:"Correct answer: Tight labor markets push nominal wages up, shifting SRAS left until Real GDP returns to potential GDP at a permanently higher price level."},
{id:"ex-a41",cat:"a",q:"Which of the following would cause BOTH an increase in Real GDP and a decrease in the price level?",opts:["A rightward shift of SRAS.","A rightward shift of AD.","A leftward shift of AD.","A leftward shift of SRAS."],exp:"Correct answer: A rightward shift of SRAS."},
{id:"ex-a42",cat:"a",q:"Which of the following would cause BOTH a decrease in Real GDP and a decrease in the price level?",opts:["A leftward shift of AD.","A rightward shift of AD.","A rightward shift of SRAS.","A leftward shift of SRAS."],exp:"Correct answer: A leftward shift of AD."},
{id:"ex-a43",cat:"a",q:"The horizontal axis of the AD-AS diagram measures:",opts:["Real GDP (Real Domestic Output).","the Consumer Price Index (CPI).","the nominal interest rate.","the quantity of money."],exp:"Correct answer: Real GDP (Real Domestic Output)."},
{id:"ex-a44",cat:"a",q:"The vertical axis of the AD-AS diagram measures:",opts:["the General Price Level (e.g., CPI or GDP Deflator).","Real GDP.","the unemployment rate.","government tax revenue."],exp:"Correct answer: the General Price Level (e.g., CPI or GDP Deflator)."},
{id:"ex-a45",cat:"a",q:"If businesses become pessimistic about future sales and cut back on purchasing new machinery, this causes:",opts:["a leftward shift of the AD curve.","a movement up along the AD curve.","a rightward shift of the AS curve.","a leftward shift of the LRAS curve."],exp:"Correct answer: a leftward shift of the AD curve."},
{id:"ex-a46",cat:"a",q:"Why does the Short-Run Aggregate Supply (SRAS) curve slope upward?",opts:["Because in the short run, output prices rise faster than sticky input prices (like wages), increasing firm profit margins and encouraging higher production.","Because higher prices reduce consumer wealth.","Because the government mandates higher production when prices rise.","Because imports become cheaper when domestic prices rise."],exp:"Correct answer: Because in the short run, output prices rise faster than sticky input prices (like wages), increasing firm profit margins and encouraging higher production."},
{id:"ex-a47",cat:"a",q:"An increase in the legal minimum wage across all industries would initially cause:",opts:["per-unit labor costs to rise, shifting the SRAS curve to the left.","the AD curve to shift left.","the LRAS curve to shift right.","interest rates to fall."],exp:"Correct answer: per-unit labor costs to rise, shifting the SRAS curve to the left."},
{id:"ex-a48",cat:"a",q:"In the 1970s, OPEC restricted global oil supplies, causing crude oil prices to quadruple. In oil-importing countries, this event caused:",opts:["stagflation (cost-push inflation + recession).","demand-pull inflation.","rapid economic expansion with falling prices.","a rightward shift of AD."],exp:"A supply shock (higher oil costs) shifts SRAS left: higher prices and lower output, which is stagflation."},
{id:"ex-a49",cat:"a",q:"According to Keynes, the most appropriate policy response to a severe recession is:",opts:["using expansionary government spending and tax cuts to shift AD to the right.","doing nothing and waiting for wages to fall.","raising taxes to balance the government budget.","restricting the money supply."],exp:"Correct answer: using expansionary government spending and tax cuts to shift AD to the right."},
{id:"ex-a50",cat:"a",q:"If an economy experiences a simultaneous rightward shift in AD and a larger rightward shift in SRAS (as occurred during the late 1990s tech boom), the macroeconomic outcome is:",opts:["rapid Real GDP growth with low or falling inflation.","stagflation.","severe deflation and high unemployment.","stagnant output with hyperinflation."],exp:"Both curves shift right, SRAS by more: output grows quickly while prices stay low or fall."},
{id:"ex-f1",cat:"f",q:"Fiscal policy refers to the use of:",opts:["government spending (G), taxation (T), and transfer payments to influence aggregate economic activity.","interest rates and the money supply by the central bank.","import tariffs and quotas by the Ministry of Commerce.","wage and price controls."],exp:"Correct answer: government spending (G), taxation (T), and transfer payments to influence aggregate economic activity."},
{id:"ex-f2",cat:"f",q:"Expansionary fiscal policy is designed to combat a recession and involves:",opts:["increasing government spending (G), cutting taxes (T), and/or increasing transfer payments.","decreasing government spending and increasing taxes.","raising interest rates and reducing the money supply.","balancing the federal budget during a downturn."],exp:"Correct answer: increasing government spending (G), cutting taxes (T), and/or increasing transfer payments."},
{id:"ex-f3",cat:"f",q:"Contractionary fiscal policy is designed to fight demand-pull inflation and involves:",opts:["decreasing government spending (G) and/or increasing taxes (T).","increasing government spending and cutting taxes.","increasing transfer payments.","lowering the reserve requirement for banks."],exp:"Correct answer: decreasing government spending (G) and/or increasing taxes (T)."},
{id:"ex-f4",cat:"f",q:"The Marginal Propensity to Consume (MPC) is defined as:",opts:["ΔConsumption / ΔDisposable Income.","Total Consumption / Total Income.","ΔSaving / ΔDisposable Income.","1 + MPS."],exp:"Correct answer: ΔConsumption / ΔDisposable Income."},
{id:"ex-f5",cat:"f",q:"Since households can only either consume or save any additional dollar of disposable income, MPC + MPS always equals:",opts:["1","0","0.5","100"],exp:"Correct answer: 1"},
{id:"ex-f6",cat:"f",q:"If the Marginal Propensity to Consume (MPC) is 0.80, what is the Marginal Propensity to Save (MPS)?",opts:["0.20","1.80","0.80","1.25"],exp:"MPS = 1 − MPC = 0.20."},
{id:"ex-f7",cat:"f",q:"The formula for the simple Government Spending Multiplier is:",opts:["1 / (1 - MPC) or 1 / MPS","1 / MPC","-MPC / (1 - MPC)","1 - MPC"],exp:"Correct answer: 1 / (1 - MPC) or 1 / MPS"},
{id:"ex-f8",cat:"f",q:"If MPC = 0.75, what is the value of the Government Spending Multiplier?",opts:["4.0","0.75","1.33","3.0"],exp:"Multiplier = 1 ÷ (1 − 0.75) = 4."},
{id:"ex-f9",cat:"f",q:"Using MPC = 0.75, if the government increases spending on new highways by $50 billion, by how much will Aggregate Demand (and Real GDP, assuming constant prices) ultimately increase?",opts:["$200 billion","$50 billion","$37.5 billion","$150 billion"],exp:"ΔAD = 4 × 50 = 200 billion."},
{id:"ex-f10",cat:"f",q:"The formula for the simple Tax Multiplier is:",opts:["-MPC / (1 - MPC) or -MPC / MPS","1 / (1 - MPC)","MPS / MPC","-1 / MPC"],exp:"Correct answer: -MPC / (1 - MPC) or -MPC / MPS"},
{id:"ex-f11",cat:"f",q:"If MPC = 0.80, what is the value of the Tax Multiplier?",opts:["-4","5","-5","4"],exp:"Tax multiplier = −MPC ÷ (1 − MPC) = −0.80 ÷ 0.20 = −4."},
{id:"ex-f12",cat:"f",q:"Using MPC = 0.80, if the government cuts personal income taxes by $25 billion, by how much will Aggregate Demand shift to the right?",opts:["$100 billion","$25 billion","$125 billion","$20 billion"],exp:"ΔAD = 4 × 25 = 100 billion."},
{id:"ex-f13",cat:"f",q:"Why is the Tax Multiplier smaller in absolute value than the Government Spending Multiplier?",opts:["Because when taxes are cut by $1, households save a portion (MPS) of that tax cut and only spend a fraction (MPC) in the first round, whereas $1 of government spending enters the spending stream entirely.","Because taxes are illegal in some states.","Because the government spends money faster than consumers.","Because tax cuts cause immediate inflation."],exp:"Correct answer: Because when taxes are cut by $1, households save a portion (MPS) of that tax cut and only spend a fraction (MPC) in the first round, whereas $1 of government spending enters the spending stream entirely."},
{id:"ex-f14",cat:"f",q:"According to the Balanced-Budget Multiplier, if the government increases spending by $40 billion AND simultaneously raises taxes by $40 billion to pay for it (keeping the budget balanced), total Aggregate Demand will:",opts:["increase by $40 billion (because the balanced-budget multiplier always equals 1).","remain unchanged ($0 change).","decrease by $40 billion.","increase by $160 billion."],exp:"The balanced-budget multiplier is 1, so ΔAD = $40 billion."},
{id:"ex-f15",cat:"f",q:"What are \"automatic stabilizers\"?",opts:["Built-in fiscal mechanisms (such as progressive income taxes and unemployment compensation) that automatically counter business cycle fluctuations without requiring new legislative action.","Laws requiring Congress to vote on new spending bills every month.","Automatic interest rate adjustments made by commercial banks.","Fixed exchange rates pegged to gold."],exp:"Correct answer: Built-in fiscal mechanisms (such as progressive income taxes and unemployment compensation) that automatically counter business cycle fluctuations without requiring new legislative action."},
{id:"ex-f16",cat:"f",q:"How do automatic stabilizers work during a recession?",opts:["As incomes fall, households drop into lower tax brackets (paying less tax) and unemployed workers automatically receive unemployment benefits, cushioning the drop in disposable income and AD.","Tax revenues automatically rise and welfare spending falls.","The government automatically balances its budget by cutting school funding.","Interest rates automatically drop to zero."],exp:"Correct answer: As incomes fall, households drop into lower tax brackets (paying less tax) and unemployed workers automatically receive unemployment benefits, cushioning the drop in disposable income and AD."},
{id:"ex-f17",cat:"f",q:"Which of the following is an example of an automatic stabilizer?",opts:["Progressive personal income taxes and unemployment insurance benefits.","A newly passed stimulus bill signed by the Prime Minister.","Construction of a new international airport.","A one-time tax rebate check mailed to voters before an election."],exp:"Correct answer: Progressive personal income taxes and unemployment insurance benefits."},
{id:"ex-f18",cat:"f",q:"\"Discretionary fiscal policy\" differs from automatic stabilizers because discretionary fiscal policy:",opts:["requires deliberate legislative action by Congress or Parliament to change tax laws or government spending programs.","happens automatically without government action.","only applies to local city governments.","is controlled by the central bank."],exp:"Correct answer: requires deliberate legislative action by Congress or Parliament to change tax laws or government spending programs."},
{id:"ex-f19",cat:"f",q:"What is the \"crowding-out effect\" of expansionary fiscal policy?",opts:["Government borrowing to finance a budget deficit increases the demand for loanable funds, driving up interest rates and reducing private business investment (I).","Government spending hires all available workers, leaving none for private firms.","Imports crowd out domestic exports.","Consumers crowd into stores during tax holidays."],exp:"Correct answer: Government borrowing to finance a budget deficit increases the demand for loanable funds, driving up interest rates and reducing private business investment (I)."},
{id:"ex-f20",cat:"f",q:"Because of the crowding-out effect, the actual expansionary impact of deficit-financed government spending on AD is:",opts:["smaller than the simple spending multiplier predicts.","larger than the simple spending multiplier predicts.","exactly equal to zero in all circumstances.","doubled."],exp:"Correct answer: smaller than the simple spending multiplier predicts."},
{id:"ex-f21",cat:"f",q:"Supply-side fiscal policy focuses on:",opts:["lowering marginal tax rates on labor and capital and reducing government regulations to increase incentives to work, save, and invest, shifting AS to the right.","increasing government transfer payments to boost consumption.","raising corporate taxes to fund public housing.","printing money to pay off the national debt."],exp:"Correct answer: lowering marginal tax rates on labor and capital and reducing government regulations to increase incentives to work, save, and invest, shifting AS to the right."},
{id:"ex-f22",cat:"f",q:"According to the Laffer Curve (associated with supply-side economics):",opts:["beyond a certain prohibitive tax rate, further increases in tax rates can actually reduce tax revenue by discouraging work, investment, and reporting.","higher tax rates always lead to higher tax revenue.","the optimal tax rate is always 100%.","taxes have no impact on economic incentives."],exp:"Correct answer: beyond a certain prohibitive tax rate, further increases in tax rates can actually reduce tax revenue by discouraging work, investment, and reporting."},
{id:"ex-f23",cat:"f",q:"A government budget deficit occurs in a given year when:",opts:["Government Expenditures > Tax Revenues.","Tax Revenues > Government Expenditures.","Exports > Imports.","National Debt = 0."],exp:"Correct answer: Government Expenditures > Tax Revenues."},
{id:"ex-f24",cat:"f",q:"A government budget surplus occurs in a given year when:",opts:["Tax Revenues > Government Expenditures.","Government Expenditures > Tax Revenues.","Imports > Exports.","Real GDP falls."],exp:"Correct answer: Tax Revenues > Government Expenditures."},
{id:"ex-f25",cat:"f",q:"The National Debt (Public Debt) is:",opts:["the total cumulative amount of money the federal government owes to creditors from all past budget deficits minus surpluses.","the annual shortfall between government spending and taxes in a single year.","the total debt owed by private households on credit cards.","the trade deficit with foreign countries."],exp:"Correct answer: the total cumulative amount of money the federal government owes to creditors from all past budget deficits minus surpluses."},
{id:"ex-f26",cat:"f",q:"Which of the following is a major timing lag that limits the effectiveness of discretionary fiscal policy?",opts:["Recognition lag, administrative (legislative) lag, and operational (impact) lag.","Exchange rate lag only.","Agricultural harvest lag.","Inventory turnover lag."],exp:"Correct answer: Recognition lag, administrative (legislative) lag, and operational (impact) lag."},
{id:"ex-f27",cat:"f",q:"Suppose an economy has a recessionary GDP gap of $300 billion (meaning AD needs to shift right by $300 billion to restore full employment). If MPC = 0.80, how much must the government increase its spending (G) to close this gap?",opts:["$60 billion","$300 billion","$75 billion","$240 billion"],exp:"Spending multiplier = 1 ÷ 0.20 = 5, so ΔG = 300 ÷ 5 = 60 billion."},
{id:"ex-f28",cat:"f",q:"Suppose an economy has a recessionary GDP gap of $300 billion (meaning AD needs to shift right by $300 billion to restore full employment) and MPC = 0.80. If the government prefers to close the gap entirely by cutting taxes instead of increasing spending, how large of a tax cut is required?",opts:["$75 billion","$60 billion","$300 billion","$240 billion"],exp:"Tax multiplier = −4, so the tax cut = 300 ÷ 4 = 75 billion."},
{id:"ex-f29",cat:"f",q:"When the government runs a budget deficit, how does it typically finance the shortfall?",opts:["By selling government bonds (treasury bills/notes) to the public, banks, and foreign investors.","By confiscating private property.","By forcing exporters to surrender their profits.","By lowering the minimum wage."],exp:"Correct answer: By selling government bonds (treasury bills/notes) to the public, banks, and foreign investors."},
{id:"ex-f30",cat:"f",q:"Which fiscal policy action is most appropriate when an economy is experiencing severe demand-pull inflation?",opts:["Raising taxes and cutting non-essential government spending.","Cutting personal income taxes and increasing defense spending.","Increasing social security benefits.","Running a larger budget deficit."],exp:"Correct answer: Raising taxes and cutting non-essential government spending."},
{id:"ex-f31",cat:"f",q:"What is the difference between an \"internally held\" public debt and an \"externally held\" public debt?",opts:["Internally held debt is owed to a nation's own citizens and domestic institutions (\"we owe it to ourselves\"), whereas externally held debt is owed to foreign governments and foreign investors.","Internally held debt never pays interest.","Externally held debt does not count toward the national debt.","Internally held debt is illegal."],exp:"Correct answer: Internally held debt is owed to a nation's own citizens and domestic institutions (\"we owe it to ourselves\"), whereas externally held debt is owed to foreign governments and foreign investors."},
{id:"ex-f32",cat:"f",q:"A major economic concern regarding a rapidly growing externally held national debt is that:",opts:["interest payments flow out of the country to foreigners, transferring real purchasing power abroad.","domestic citizens become too wealthy.","it causes immediate deflation.","it eliminates the need for taxes."],exp:"Correct answer: interest payments flow out of the country to foreigners, transferring real purchasing power abroad."},
{id:"ex-f33",cat:"f",q:"If the Marginal Propensity to Save (MPS) increases from 0.20 to 0.25, what happens to the Government Spending Multiplier?",opts:["It decreases from 5 to 4.","It increases from 5 to 6.","It increases from 4 to 5.","It remains unchanged at 5."],exp:"Multiplier = 1 ÷ MPS: 1 ÷ 0.20 = 5 falls to 1 ÷ 0.25 = 4."},
{id:"ex-f34",cat:"f",q:"Why does a higher Marginal Propensity to Save (MPS) result in a smaller spending multiplier?",opts:["Because more of each dollar of new income leaks out into saving rather than being re-spent on consumption.","Because banks stop lending money.","Because taxes automatically increase.","Because imports decrease."],exp:"Correct answer: Because more of each dollar of new income leaks out into saving rather than being re-spent on consumption."},
{id:"ex-f35",cat:"f",q:"In real-world open economies, what else besides saving reduces the size of the spending multiplier?",opts:["Income taxes and spending on imports (leakages from the domestic circular flow).","Higher domestic consumption.","Falling interest rates.","Lower unemployment."],exp:"Correct answer: Income taxes and spending on imports (leakages from the domestic circular flow)."},
{id:"ex-f36",cat:"f",q:"Supply-side economists argue that reducing high marginal tax rates on businesses and investors will:",opts:["stimulate capital investment, innovation, and job creation, shifting AS right.","decrease aggregate supply.","cause severe stagflation.","reduce labor force participation."],exp:"Correct answer: stimulate capital investment, innovation, and job creation, shifting AS right."},
{id:"ex-f37",cat:"f",q:"During a recession, if a government strictly follows an \"annually balanced budget\" rule (cutting spending and raising taxes as tax revenues fall), this policy would:",opts:["be pro-cyclical, making the recession deeper and more severe.","quickly cure the recession.","have no effect on Aggregate Demand.","act as an automatic stabilizer."],exp:"Correct answer: be pro-cyclical, making the recession deeper and more severe."},
{id:"ex-f38",cat:"f",q:"A \"cyclically balanced budget\" philosophy argues that the government should:",opts:["run budget deficits during recessions to stimulate the economy and run budget surpluses during inflationary booms to pay down the debt over the course of the business cycle.","balance its budget every single month.","never collect taxes.","maintain a permanent deficit regardless of economic conditions."],exp:"Correct answer: run budget deficits during recessions to stimulate the economy and run budget surpluses during inflationary booms to pay down the debt over the course of the business cycle."},
{id:"ex-f39",cat:"f",q:"Suppose an economy is at equilibrium with Real GDP = $1,000 billion, while Potential Real GDP = $1,120 billion. If MPC = 0.75 and the price level is constant (Keynesian range), what fiscal action will restore full employment?",opts:["Increase government spending by $30 billion.","Increase government spending by $120 billion.","Cut taxes by $30 billion.","Increase taxes by $40 billion."],exp:"GDP gap = 120. Multiplier = 1 ÷ 0.25 = 4. ΔG = 120 ÷ 4 = 30 billion."},
{id:"ex-f40",cat:"f",q:"Which of the following is an example of \"functional finance\"?",opts:["Focusing fiscal policy primarily on achieving full employment and price stability rather than worrying about whether the budget is balanced in any particular year.","Balancing the budget at all costs.","Financing all government projects through foreign aid.","Eliminating the central bank."],exp:"Correct answer: Focusing fiscal policy primarily on achieving full employment and price stability rather than worrying about whether the budget is balanced in any particular year."},
{id:"ex-f41",cat:"f",q:"Why might households fail to spend a temporary, one-time tax cut (such as a single stimulus check)?",opts:["According to the Permanent Income Hypothesis, consumers base spending mostly on their long-run expected income and tend to save temporary windfalls.","Temporary tax cuts are illegal to spend.","Prices double the day the check arrives.","Banks refuse to cash government checks."],exp:"Correct answer: According to the Permanent Income Hypothesis, consumers base spending mostly on their long-run expected income and tend to save temporary windfalls."},
{id:"ex-f42",cat:"f",q:"Which branch of the U.S. government is responsible for enacting fiscal policy?",opts:["Congress and the President","The Federal Reserve Board","The Supreme Court","Commercial banks"],exp:"Correct answer: Congress and the President"},
{id:"ex-f43",cat:"f",q:"If government spending (G) increases by $10 billion and household saving increases by $10 billion at the same time, the net effect on Aggregate Demand is:",opts:["zero, because the $10 billion injection of government spending is offset by the $10 billion leakage into saving.","an increase of $10 billion multiplied by the multiplier.","a decrease of $20 billion.","an increase of $20 billion."],exp:"The $10 billion injection from government spending is offset by a $10 billion leakage into saving, so AD does not change."},
{id:"ex-f44",cat:"f",q:"Suppose MPC = 0.60. If the government increases spending by $100 billion and cuts taxes by $100 billion simultaneously, what is the total combined shift in Aggregate Demand?",opts:["$400 billion","$250 billion","$150 billion","$500 billion"],exp:"Spending: 2.5 × 100 = 250. Tax cut: 1.5 × 100 = 150. Total = 400 billion."},
{id:"ex-f45",cat:"f",q:"Infrastructure spending (building roads, bridges, high-speed rail, and broadband internet) is unique among fiscal policies because:",opts:["it boosts AD in the short run AND increases the economy's productive capacity (shifting LRAS right) in the long run.","it has a multiplier of zero.","it reduces private sector productivity.","it only helps foreign tourists."],exp:"Correct answer: it boosts AD in the short run AND increases the economy's productive capacity (shifting LRAS right) in the long run."},
{id:"ex-f46",cat:"f",q:"Which of the following would cause a \"structural budget deficit\" (a deficit that exists even when the economy is at full employment)?",opts:["Permanent tax cuts combined with high ongoing entitlement spending programs when the economy is already operating at potential GDP.","A temporary spike in unemployment during a recession.","A sudden surge in corporate tax collections during a boom.","A trade surplus."],exp:"Correct answer: Permanent tax cuts combined with high ongoing entitlement spending programs when the economy is already operating at potential GDP."},
{id:"ex-f47",cat:"f",q:"In the formula Multiplier = 1 / (1 - MPC), as the MPC gets larger (closer to 1), the multiplier:",opts:["gets larger.","gets smaller.","stays equal to 1.","becomes negative."],exp:"As MPC approaches 1, 1 ÷ (1 − MPC) gets larger."},
{id:"ex-f48",cat:"f",q:"Political business cycles occur when:",opts:["politicians use expansionary fiscal policy (tax cuts and spending hikes) right before an election to boost employment and win votes, even if it causes inflation later.","elections are canceled during recessions.","central banks run for political office.","voters demand higher taxes."],exp:"Correct answer: politicians use expansionary fiscal policy (tax cuts and spending hikes) right before an election to boost employment and win votes, even if it causes inflation later."},
{id:"ex-f49",cat:"f",q:"How can a government reduce its debt-to-GDP ratio without running a budget surplus?",opts:["By ensuring that the rate of economic growth (Nominal GDP growth) exceeds the interest rate paid on the national debt.","By defaulting on all government bonds.","By raising tariffs to 100%.","By eliminating all public schools."],exp:"Correct answer: By ensuring that the rate of economic growth (Nominal GDP growth) exceeds the interest rate paid on the national debt."},
{id:"ex-f50",cat:"f",q:"Suppose an economy is experiencing an inflationary gap where AD exceeds full-employment output by $150 billion. If MPC = 0.75, which contractionary fiscal policy will bring AD back to full employment?",opts:["Decrease government spending by $37.5 billion, OR increase taxes by $50 billion.","Decrease government spending by $50 billion, OR increase taxes by $37.5 billion.","Increase government spending by $37.5 billion.","Cut taxes by $50 billion."],exp:"AD must fall by 150. Spending multiplier 4: cut G by 37.5. Tax multiplier −3: raise taxes by 50."}
]);
